manifests.Cargo.toml:
[workspace.package]
version = "0.0.0"
edition = "2024"
rust-version = "1.95"
license = "MIT"
homepage = "https://github.com/base/base"
repository = "https://github.com/base/base"
exclude = [".github/"]

[workspace]
resolver = "2"
exclude = ["bin/prover", "crates/proof/succinct/programs", "actions/fixtures"]
members = [
  "bin/*",
  "bin/prover/nitro-host",
  "bin/prover/nitro-enclave",
  "bin/prover/zk-host",
  "bin/prover/service",
  "crates/proof/mpt",
  "crates/proof/proof",
  "crates/proof/driver",
  "crates/proof/client",
  "crates/proof/executor",
  "crates/proof/preimage",
  "crates/proof/primitives",
  "crates/proof/host",
  "crates/proof/prover-service",
  "crates/proof/prover-service/client",
  "crates/proof/prover-service/protocol",
  "crates/proof/prover-service/db",
  "crates/proof/worker",
  "crates/proof/tee/nitro-host",
  "crates/proof/tee/nitro-enclave",
  "crates/proof/tee/registrar",
  "crates/proof/tee/nitro-verifier",
  "crates/proof/tee/nitro-attestation-prover",
  "crates/proof/zk/host",
  "crates/proof/zk/backend",
  "crates/proof/contracts",
  "crates/proof/submission",
  "crates/proof/rpc",
  "crates/proof/proposer",
  "crates/proof/challenge",
  "crates/proof/succinct/utils/client",
  "crates/proof/succinct/utils/host",
  "crates/proof/succinct/utils/proof",
  "crates/proof/succinct/utils/elfs",
  "crates/proof/succinct/scripts",

  "crates/execution/*",
  "crates/consensus/*",
  "crates/utilities/*",
  "crates/batcher/*",
  "crates/builder/*",
  "crates/common/*",
  "crates/infra/*",
  "etc/tools/*",
  "etc/systems",
  "actions/*",
]
default-members = [
  "bin/*",
  "bin/prover/nitro-host",
  "bin/prover/nitro-enclave",
  "bin/prover/zk-host",
  "bin/prover/service",
  "bin/prover-registrar",
]

[workspace.metadata.cargo-udeps.ignore]
normal = ["rustls-platform-verifier"]

[workspace.lints.rust]
missing-debug-implementations = "warn"
missing-docs = "warn"
unreachable-pub = "warn"
unused-must-use = "deny"
rust-2018-idioms = "deny"
unnameable-types = "warn"

[workspace.lints.rustdoc]
all = "warn"

[workspace.lints.clippy]
# Baseline - enable all default clippy lints
all = { level = "warn", priority = -1 }

# === Performance & Cloning ===
missing-const-for-fn = "warn"
redundant-clone = "warn"
clone-on-ref-ptr = "warn"
unnecessary-to-owned = "warn"
cloned-instead-of-copied = "warn"
flat-map-option = "warn"
implicit-clone = "warn"
or-fun-call = "warn"

# === Code Style ===
wildcard-imports = "warn"
use-self = "warn"
option-if-let-else = "warn"
uninlined-format-args = "warn"
manual-string-new = "warn"
single-char-pattern = "warn"
redundant-else = "warn"
match-same-arms = "warn"

# === Safety & Documentation ===
undocumented-unsafe-blocks = "warn"
doc-markdown = "warn"

# === Debugging Artifacts ===
dbg-macro = "warn"

# === Code Quality ===
branches-sharing-code = "warn"
derive-partial-eq-without-eq = "warn"
explicit-into-iter-loop = "warn"
explicit-iter-loop = "warn"
iter-with-drain = "warn"
needless-pass-by-ref-mut = "warn"
string-lit-as-bytes = "warn"

[profile.dev]
debug = "line-tables-only"
incremental = true

[profile.release]
opt-level = 3
lto = "thin"
debug = "none"
strip = "symbols"
panic = "unwind"
codegen-units = 16

[profile.maxperf]
inherits = "release"
lto = "fat"
codegen-units = 1

# TODO: add `rustflags = ["-Cforce-frame-pointers=yes"]` here once
# `profile-rustflags` is stabilized (tracking: rust-lang/cargo#10271)
[profile.profiling]
inherits = "release"
lto = false
debug = "line-tables-only"
strip = "none"

# CI profile: optimized for fast GHA builds and minimal disk usage
[profile.ci]
inherits = "dev"
debug = false
incremental = false

