        },
        "filenames": [
          "blender",
          "blender.exe",
          "blender-launcher",
          "blender-launcher.exe"
        ]
      }
    ]
  },
  "scripts": {
    "vscode:prepublish": "npm run compile",
    "compile": "tsc -p ./",
    "watch": "tsc -watch -p ./",
    "lint": "eslint \"src/**/*.ts\" --max-warnings=0"
  },
