        },
        "go.goplsUseDaemon": {
          "type": "boolean",
          "default": true,
          "description": "Run gopls as daemon"
        },
        "go.disable": {
          "type": "object",
          "description": "Disable gopls features",
          "default": {},
          "properties": {
            "workspaceFolders": {
              "type": "boolean",
