              "default": "json=omitempty",
              "description": "Comma separated tag=options pairs to be used by `go.tags.add` command"
            },
            "transform": {
              "type": "string",
              "enum": [
                "snakecase",
                "camelcase"
              ],
              "default": "snakecase",
              "description": "Transformation rule used by `go.tags.add` command to add tags"
